#include <bits/stdc++.h>
#define ll long long
using namespace std;

const ll maxn = 2e5 + 5;
const ll mod = 998244353;
ll n, m, fac[maxn], inv[maxn], s;

ll pow_mod(ll a, ll b)
{
    ll ret = 1;
    while (b)
    {
        if (b & 1) ret = ret * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return ret;
}

void init()
{
    fac[0] = 1;
    for (int i = 1; i < maxn; i++)
    {
        fac[i] = fac[i - 1] * i % mod;
    }
}

ll Cc(ll x, ll y)
{
    return fac[x] * pow_mod(fac[y] * fac[x - y] % mod, mod - 2) % mod;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;
    if (n == 2)
    {
        cout << 0 << '\n';
    }
    else
    {
        init();
        s = Cc(m, n - 1) * (n - 2) % mod;
        s = s * pow_mod(2, n - 3) % mod;
        cout << s << '\n';
    }

    return 0;
}

